def executar_consulta_segura(consulta_firestore):
    try:
        return [{doc.id: doc.to_dict()} for doc in consulta_firestore.stream()]
    except exceptions.FailedPrecondition as erro:
        url_indice = re.search(r'(https://console\.firebase\.google\.com/[^\s]+)', str(erro))
        return {'status': 'erro-indice-ausente', 'link-para-criar-indice': url_indice.group(0) if url_indice else None}

match /produtos/{produtoId} {
  allow read: if usuarioAutenticado();
  allow write: if possuiPapel('administrador') && request.resource.data.preco > 0;
}
